import Root from './calendar.svelte';
import Caption from './calendar-caption.svelte';
import Cell from './calendar-cell.svelte';
import Day from './calendar-day.svelte';
import Grid from './calendar-grid.svelte';
import GridBody from './calendar-grid-body.svelte';
import GridHead from './calendar-grid-head.svelte';
import GridRow from './calendar-grid-row.svelte';
import HeadCell from './calendar-head-cell.svelte';
import Header from './calendar-header.svelte';
import Heading from './calendar-heading.svelte';
import Month from './calendar-month.svelte';
import MonthSelect from './calendar-month-select.svelte';
import Months from './calendar-months.svelte';
import Nav from './calendar-nav.svelte';
import NextButton from './calendar-next-button.svelte';
import PrevButton from './calendar-prev-button.svelte';
import YearSelect from './calendar-year-select.svelte';

export {
  Caption,
  Cell,
  Day,
  Grid,
  GridBody,
  GridHead,
  GridRow,
  HeadCell,
  Header,
  Heading,
  Month,
  MonthSelect,
  Months,
  Nav,
  NextButton,
  PrevButton,
  //
  Root as Calendar,
  YearSelect
};

import { isHTMLElement, srOnlyStylesString } from 'svelte-toolbelt';
import { isBrowser } from './is';

type AnnouncementKind = 'assertive' | 'polite';

/**
 * Creates or gets an announcer element used to announce messages to screen readers.
 */
function initAnnouncer(doc: Document | null) {
  if (!isBrowser || !doc) return null;
  let el = doc.querySelector('[data-bits-announcer]');

  const createLog = (kind: AnnouncementKind) => {
    const log = doc.createElement('div');
    log.role = 'log';
    log.ariaLive = kind;
    log.setAttribute('aria-relevant', 'additions');
    return log;
  };

  if (!isHTMLElement(el)) {
    const div = doc.createElement('div');
    div.style.cssText = srOnlyStylesString;
    div.setAttribute('data-bits-announcer', '');
    div.appendChild(createLog('assertive'));
    div.appendChild(createLog('polite'));
    el = div;
    doc.body.insertBefore(el, doc.body.firstChild);
  }

  const getLog = (kind: AnnouncementKind) => {
    if (!isHTMLElement(el)) return null;
    const log = el.querySelector(`[aria-live="${kind}"]`);
    if (!isHTMLElement(log)) return null;
    return log;
  };

  return { getLog };
}

/**
 * Creates an announcer object used to make `aria-live` announcements to screen readers.
 */
export function getAnnouncer(doc: Document | null) {
  const announcer = initAnnouncer(doc);

  function announce(
    value: string | number | null,
    kind: AnnouncementKind = 'assertive',
    timeout = 7500
  ) {
    if (!announcer || !isBrowser || !doc) return;
    const log = announcer.getLog(kind);
    const content = doc.createElement('div');
    let text: string;
    if (typeof value === 'number') {
      text = value.toString();
    } else if (value === null) {
      text = 'Empty';
    } else {
      text = value.trim();
    }
    content.innerText = text;
    if (kind === 'assertive') {
      log?.replaceChildren(content);
    } else {
      log?.appendChild(content);
    }
    return setTimeout(() => {
      content.remove();
    }, timeout);
  }

  return { announce };
}

/**
 * Splits an array into chunks of a given size.
 */
export function chunk<T>(arr: T[], size: number): T[][] {
  if (size <= 0) return [];
  const result: T[][] = [];
  for (let i = 0; i < arr.length; i += size) {
    result.push(arr.slice(i, i + size));
  }
  return result;
}

/**
 * Checks if the given index is valid for the given array.
 */
export function isValidIndex(index: number, arr: unknown[]) {
  return index >= 0 && index < arr.length;
}

export function boolToStr(condition: boolean): 'true' | 'false' {
  return condition ? 'true' : 'false';
}

export function boolToStrTrueOrUndef(condition: boolean): 'true' | undefined {
  return condition ? 'true' : undefined;
}

export function boolToEmptyStrOrUndef(condition: boolean): '' | undefined {
  return condition ? '' : undefined;
}

class BitsAttrs<T extends readonly string[]> {
  #prefix: string;
  attrs: Record<T[number], string>;

  constructor(config: { component: string; parts: T }) {
    this.#prefix = `data-${config.component}-`;
    this.getAttr = this.getAttr.bind(this);
    this.attrs = Object.fromEntries(
      config.parts.map((part) => [part, this.getAttr(part)])
    ) as Record<T[number], string>;
  }

  getAttr(part: string, variantOverride?: string) {
    if (variantOverride) return `data-${variantOverride}-${part}`;
    return `${this.#prefix}${part}`;
  }
}

export function createBitsAttrs<T extends readonly string[]>(config: {
  component: string;
  parts: T;
}) {
  const bitsAttrs = new BitsAttrs(config);
  return {
    ...bitsAttrs.attrs,
    getAttr: bitsAttrs.getAttr
  };
}

import { Context } from 'runed';
import { boxWith, type ReadableBox } from 'svelte-toolbelt';

type ConfigOpts = {
  defaultLocale?: ReadableBox<string | undefined>;
};

/**
 * Configuration state that inherits from parent configurations. Only the
 * `defaultLocale` option is vendored here, as it's the only one used by
 * the Calendar/RangeCalendar components.
 */
class BitsConfigState {
  opts: { defaultLocale: ReadableBox<string | undefined> };

  constructor(parent: BitsConfigState | null, opts: ConfigOpts) {
    this.opts = {
      defaultLocale: boxWith<string | undefined>(() => {
        const value = opts.defaultLocale?.current;
        if (value !== undefined) return value;
        if (parent === null) return undefined;
        return parent.opts.defaultLocale.current;
      })
    };
  }
}

const BitsConfigContext = new Context<BitsConfigState>('BitsConfig');

/**
 * Gets the current Bits configuration state from the context.
 * Returns a default configuration if no configuration is found.
 */
export function getBitsConfig() {
  const fallback = new BitsConfigState(null, {});
  return BitsConfigContext.getOr(fallback).opts;
}

import { type DateValue, endOfMonth, isSameDay, isSameMonth, startOfMonth } from '@internationalized/date';
import { watch } from 'runed';
import { afterTick, getDocument, isHTMLElement, styleToString } from 'svelte-toolbelt';
import type { ReadableBox, WritableBox } from 'svelte-toolbelt';
import type { Month } from './types';
import { boolToEmptyStrOrUndef, createBitsAttrs } from './attrs';
import { chunk, isValidIndex } from './arrays';
import { isBrowser } from './is';
import { kbd } from './kbd';
import type { Formatter } from './formatter';
import {
  type DateValueType,
  getDaysInMonth,
  getLastFirstDayOfWeek,
  getNextLastDayOfWeek,
  hasTime,
  isAfter,
  isBefore,
  parseAnyDateValue,
  parseStringToDateValue,
  toDate
} from './date-utils';

/**
 * Checks if a given node is a calendar cell element.
 */
export function isCalendarDayNode(node: unknown): node is HTMLElement {
  if (!isHTMLElement(node)) return false;
  if (!node.hasAttribute('data-bits-day')) return false;
  return true;
}

/**
 * Retrieves an array of date values representing the days between
 * the provided start and end dates.
 */
export function getDaysBetween(start: DateValue, end: DateValue): DateValue[] {
  const days: DateValue[] = [];
  let dCurrent = start.add({ days: 1 });
  const dEnd = end;
  while (dCurrent.compare(dEnd) < 0) {
    days.push(dCurrent);
    dCurrent = dCurrent.add({ days: 1 });
  }
  return days;
}

type CreateMonthProps = {
  dateObj: DateValue;
  weekStartsOn: number | undefined;
  fixedWeeks: boolean;
  locale: string;
};

/**
 * Creates a calendar month object: the month's date (the first day of that
 * month), an array of all dates in that month, and an array of weeks, each
 * an array of dates, for rendering an accessible calendar grid.
 */
function createMonth(props: CreateMonthProps): Month<DateValue> {
  const { dateObj, weekStartsOn, fixedWeeks, locale } = props;
  const daysInMonth = getDaysInMonth(dateObj);
  const datesArray = Array.from({ length: daysInMonth }, (_, i) => dateObj.set({ day: i + 1 }));
  const firstDayOfMonth = startOfMonth(dateObj);
  const lastDayOfMonth = endOfMonth(dateObj);
  const lastSunday =
    weekStartsOn !== undefined
      ? getLastFirstDayOfWeek(firstDayOfMonth, weekStartsOn, 'en-US')
      : getLastFirstDayOfWeek(firstDayOfMonth, 0, locale);
  const nextSaturday =
    weekStartsOn !== undefined
      ? getNextLastDayOfWeek(lastDayOfMonth, weekStartsOn, 'en-US')
      : getNextLastDayOfWeek(lastDayOfMonth, 0, locale);
  const lastMonthDays = getDaysBetween(lastSunday.subtract({ days: 1 }), firstDayOfMonth);
  const nextMonthDays = getDaysBetween(lastDayOfMonth, nextSaturday.add({ days: 1 }));
  const totalDays = lastMonthDays.length + datesArray.length + nextMonthDays.length;

  if (fixedWeeks && totalDays < 42) {
    const extraDays = 42 - totalDays;
    let startFrom = nextMonthDays[nextMonthDays.length - 1];
    if (!startFrom) {
      startFrom = dateObj.add({ months: 1 }).set({ day: 1 });
    }
    let length = extraDays;
    if (nextMonthDays.length === 0) {
      length = extraDays - 1;
      nextMonthDays.push(startFrom);
    }
    const extraDaysArray = Array.from({ length }, (_, i) => {
      const incr = i + 1;
      return startFrom.add({ days: incr });
    });
    nextMonthDays.push(...extraDaysArray);
  }

  const allDays = lastMonthDays.concat(datesArray, nextMonthDays);
  const weeks = chunk(allDays, 7);

  return {
    value: dateObj,
    dates: allDays,
    weeks
  };
}

export function createMonths(
  props: CreateMonthProps & {
    numberOfMonths: number | undefined;
  }
): Month<DateValue>[] {
  const { numberOfMonths, dateObj, ...monthProps } = props;
  const months: Month<DateValue>[] = [];
  if (!numberOfMonths || numberOfMonths === 1) {
    months.push(createMonth({ ...monthProps, dateObj }));
    return months;
  }
  months.push(createMonth({ ...monthProps, dateObj }));
  for (let i = 1; i < numberOfMonths; i++) {
    const nextMonth = dateObj.add({ months: i });
    months.push(createMonth({ ...monthProps, dateObj: nextMonth }));
  }
  return months;
}

export function getSelectableCells(calendarNode: HTMLElement | null): HTMLElement[] {
  if (!calendarNode) return [];
  const selectableSelector = `[data-bits-day]:not([data-disabled]):not([data-outside-visible-months])`;
  return Array.from(calendarNode.querySelectorAll(selectableSelector)).filter((el) => isHTMLElement(el));
}

/**
 * Extracts the date from the `data-value` attribute of a date cell and
 * sets it as the placeholder value.
 */
export function setPlaceholderToNodeValue(node: HTMLElement, placeholder: WritableBox<DateValue>) {
  const cellValue = node.getAttribute('data-value');
  if (!cellValue) return;
  placeholder.current = parseStringToDateValue(cellValue, placeholder.current);
}

/**
 * Shared logic for shifting focus between cells in the calendar and range calendar.
 */
export function shiftCalendarFocus({
  node,
  add,
  placeholder,
  calendarNode,
  isPrevButtonDisabled,
  isNextButtonDisabled,
  months,
  numberOfMonths
}: {
  node: HTMLElement;
  add: number;
  placeholder: WritableBox<DateValue>;
  calendarNode: HTMLElement | null;
  isPrevButtonDisabled: boolean;
  isNextButtonDisabled: boolean;
  months: Month<DateValue>[];
  numberOfMonths: number;
}) {
  const candidateCells = getSelectableCells(calendarNode);
  if (!candidateCells.length) return;
  const index = candidateCells.indexOf(node);
  const nextIndex = index + add;

  if (isValidIndex(nextIndex, candidateCells)) {
    const nextCell = candidateCells[nextIndex];
    setPlaceholderToNodeValue(nextCell, placeholder);
    return nextCell.focus();
  }

  if (nextIndex < 0) {
    if (isPrevButtonDisabled) return;
    const firstMonth = months[0]?.value;
    if (!firstMonth) return;
    placeholder.current = firstMonth.subtract({ months: numberOfMonths });
    afterTick(() => {
      const newCandidateCells = getSelectableCells(calendarNode);
      if (!newCandidateCells.length) return;
      const newIndex = newCandidateCells.length - Math.abs(nextIndex);
      if (isValidIndex(newIndex, newCandidateCells)) {
        const newCell = newCandidateCells[newIndex];
        setPlaceholderToNodeValue(newCell, placeholder);
        return newCell.focus();
      }
    });
  }

  if (nextIndex >= candidateCells.length) {
    if (isNextButtonDisabled) return;
    const firstMonth = months[0]?.value;
    if (!firstMonth) return;
    placeholder.current = firstMonth.add({ months: numberOfMonths });
    afterTick(() => {
      const newCandidateCells = getSelectableCells(calendarNode);
      if (!newCandidateCells.length) return;
      const newIndex = nextIndex - candidateCells.length;
      if (isValidIndex(newIndex, newCandidateCells)) {
        const nextCell = newCandidateCells[newIndex];
        return nextCell.focus();
      }
    });
  }
}

const ARROW_KEYS: string[] = [kbd.ARROW_DOWN, kbd.ARROW_UP, kbd.ARROW_LEFT, kbd.ARROW_RIGHT];
const SELECT_KEYS: string[] = [kbd.ENTER, kbd.SPACE];

/**
 * Shared keyboard event handler for the calendar and range calendar.
 */
export function handleCalendarKeydown({
  event,
  handleCellClick,
  shiftFocus,
  placeholderValue
}: {
  event: KeyboardEvent;
  handleCellClick: (e: Event, date: DateValue) => void;
  shiftFocus: (node: HTMLElement, add: number) => void;
  placeholderValue: DateValue;
}) {
  const currentCell = event.target;
  if (!isCalendarDayNode(currentCell)) return;
  if (!ARROW_KEYS.includes(event.key) && !SELECT_KEYS.includes(event.key)) return;
  event.preventDefault();

  const kbdFocusMap: Record<string, number> = {
    [kbd.ARROW_DOWN]: 7,
    [kbd.ARROW_UP]: -7,
    [kbd.ARROW_LEFT]: -1,
    [kbd.ARROW_RIGHT]: 1
  };

  if (ARROW_KEYS.includes(event.key)) {
    const add = kbdFocusMap[event.key];
    if (add !== undefined) {
      shiftFocus(currentCell, add);
    }
  }

  if (SELECT_KEYS.includes(event.key)) {
    const cellValue = currentCell.getAttribute('data-value');
    if (!cellValue) return;
    handleCellClick(event, parseStringToDateValue(cellValue, placeholderValue));
  }
}

type PageNavProps = {
  months: Month<DateValue>[];
  setMonths: (months: Month<DateValue>[]) => void;
  numberOfMonths: number;
  pagedNavigation: boolean;
  weekStartsOn: number | undefined;
  locale: string;
  fixedWeeks: boolean;
  setPlaceholder: (date: DateValue) => void;
};

export function handleCalendarNextPage({
  months,
  setMonths,
  numberOfMonths,
  pagedNavigation,
  weekStartsOn,
  locale,
  fixedWeeks,
  setPlaceholder
}: PageNavProps) {
  const firstMonth = months[0]?.value;
  if (!firstMonth) return;
  if (pagedNavigation) {
    setPlaceholder(firstMonth.add({ months: numberOfMonths }));
  } else {
    const targetDate = firstMonth.add({ months: 1 });
    const newMonths = createMonths({
      dateObj: targetDate,
      weekStartsOn,
      locale,
      fixedWeeks,
      numberOfMonths
    });
    setPlaceholder(targetDate);
    setMonths(newMonths);
  }
}

export function handleCalendarPrevPage({
  months,
  setMonths,
  numberOfMonths,
  pagedNavigation,
  weekStartsOn,
  locale,
  fixedWeeks,
  setPlaceholder
}: PageNavProps) {
  const firstMonth = months[0]?.value;
  if (!firstMonth) return;
  if (pagedNavigation) {
    setPlaceholder(firstMonth.subtract({ months: numberOfMonths }));
  } else {
    const targetDate = firstMonth.subtract({ months: 1 });
    const newMonths = createMonths({
      dateObj: targetDate,
      weekStartsOn,
      locale,
      fixedWeeks,
      numberOfMonths
    });
    setPlaceholder(targetDate);
    setMonths(newMonths);
  }
}

export function getWeekdays({
  months,
  formatter,
  weekdayFormat
}: {
  months: Month<DateValue>[];
  formatter: Formatter;
  weekdayFormat: Intl.DateTimeFormatOptions['weekday'];
}): string[] {
  if (!months.length) return [];
  const firstMonth = months[0];
  const firstWeek = firstMonth.weeks[0];
  if (!firstWeek) return [];
  return firstWeek.map((date) => formatter.dayOfWeek(toDate(date), weekdayFormat));
}

/**
 * Updates the displayed months based on changes in the options values,
 * which determines the month to show in the calendar.
 */
export function useMonthViewOptionsSync(props: {
  weekStartsOn: ReadableBox<number | undefined>;
  locale: ReadableBox<string>;
  fixedWeeks: ReadableBox<boolean>;
  numberOfMonths: ReadableBox<number>;
  placeholder: ReadableBox<DateValue>;
  setMonths: (months: Month<DateValue>[]) => void;
}) {
  $effect(() => {
    const weekStartsOn = props.weekStartsOn.current;
    const locale = props.locale.current;
    const fixedWeeks = props.fixedWeeks.current;
    const numberOfMonths = props.numberOfMonths.current;
    const placeholder = props.placeholder.current;
    if (!placeholder) return;
    const defaultMonthProps = { weekStartsOn, locale, fixedWeeks, numberOfMonths };
    props.setMonths(createMonths({ ...defaultMonthProps, dateObj: placeholder }));
  });
}

/**
 * Creates an accessible heading element for the calendar. Returns a
 * function that removes the heading element.
 */
export function createAccessibleHeading({
  calendarNode,
  label,
  accessibleHeadingId
}: {
  calendarNode: HTMLElement;
  label: string;
  accessibleHeadingId: string;
}) {
  const doc = getDocument(calendarNode);
  const div = doc.createElement('div');
  div.style.cssText = styleToString({
    border: '0px',
    clip: 'rect(0px, 0px, 0px, 0px)',
    clipPath: 'inset(50%)',
    height: '1px',
    margin: '-1px',
    overflow: 'hidden',
    padding: '0px',
    position: 'absolute',
    whiteSpace: 'nowrap',
    width: '1px'
  });
  const h2 = doc.createElement('div');
  h2.textContent = label;
  h2.id = accessibleHeadingId;
  h2.role = 'heading';
  h2.ariaLevel = '2';
  calendarNode.insertBefore(div, calendarNode.firstChild);
  div.appendChild(h2);
  return () => {
    const heading = doc.getElementById(accessibleHeadingId);
    if (!heading) return;
    div.parentElement?.removeChild(div);
    heading.remove();
  };
}

export function useMonthViewPlaceholderSync({
  placeholder,
  getVisibleMonths,
  weekStartsOn,
  locale,
  fixedWeeks,
  numberOfMonths,
  setMonths
}: {
  placeholder: ReadableBox<DateValue>;
  getVisibleMonths: () => DateValue[];
  weekStartsOn: ReadableBox<number | undefined>;
  locale: ReadableBox<string>;
  fixedWeeks: ReadableBox<boolean>;
  numberOfMonths: ReadableBox<number>;
  setMonths: (months: Month<DateValue>[]) => void;
}) {
  $effect(() => {
    if (getVisibleMonths().some((month) => isSameMonth(month, placeholder.current))) {
      return;
    }
    const defaultMonthProps = {
      weekStartsOn: weekStartsOn.current,
      locale: locale.current,
      fixedWeeks: fixedWeeks.current,
      numberOfMonths: numberOfMonths.current
    };
    setMonths(createMonths({ ...defaultMonthProps, dateObj: placeholder.current }));
  });
}

export function getIsNextButtonDisabled({
  maxValue,
  months,
  disabled
}: {
  maxValue: DateValue | undefined;
  months: Month<DateValue>[];
  disabled: boolean;
}) {
  if (!maxValue || !months.length) return false;
  if (disabled) return true;
  const lastMonthInView = months[months.length - 1]?.value;
  if (!lastMonthInView) return false;
  const firstMonthOfNextPage = lastMonthInView.add({ months: 1 }).set({ day: 1 });
  return isAfter(firstMonthOfNextPage, maxValue);
}

export function getIsPrevButtonDisabled({
  minValue,
  months,
  disabled
}: {
  minValue: DateValue | undefined;
  months: Month<DateValue>[];
  disabled: boolean;
}) {
  if (!minValue || !months.length) return false;
  if (disabled) return true;
  const firstMonthInView = months[0]?.value;
  if (!firstMonthInView) return false;
  const lastMonthOfPrevPage = firstMonthInView.subtract({ months: 1 }).set({ day: 35 });
  return isBefore(lastMonthOfPrevPage, minValue);
}

export function getCalendarHeadingValue({
  months,
  locale,
  formatter
}: {
  months: Month<DateValue>[];
  locale: string;
  formatter: Formatter;
}) {
  if (!months.length) return '';
  if (locale !== formatter.getLocale()) {
    formatter.setLocale(locale);
  }
  if (months.length === 1) {
    const month = toDate(months[0].value);
    return `${formatter.fullMonthAndYear(month)}`;
  }
  const startMonth = toDate(months[0].value);
  const endMonth = toDate(months[months.length - 1].value);
  const startMonthName = formatter.fullMonth(startMonth);
  const endMonthName = formatter.fullMonth(endMonth);
  const startMonthYear = formatter.fullYear(startMonth);
  const endMonthYear = formatter.fullYear(endMonth);
  return startMonthYear === endMonthYear
    ? `${startMonthName} - ${endMonthName} ${endMonthYear}`
    : `${startMonthName} ${startMonthYear} - ${endMonthName} ${endMonthYear}`;
}

export function getCalendarElementProps({
  fullCalendarLabel,
  id,
  isInvalid,
  disabled,
  readonly
}: {
  fullCalendarLabel: string;
  id: string;
  isInvalid: boolean;
  disabled: boolean;
  readonly: boolean;
}) {
  return {
    id,
    role: 'application',
    'aria-label': fullCalendarLabel,
    'data-invalid': boolToEmptyStrOrUndef(isInvalid),
    'data-disabled': boolToEmptyStrOrUndef(disabled),
    'data-readonly': boolToEmptyStrOrUndef(readonly)
  };
}

export function getFirstNonDisabledDateInView(calendarRef: HTMLElement): DateValue | undefined {
  if (!isBrowser) return;
  const daysInView = Array.from(calendarRef.querySelectorAll('[data-bits-day]:not([aria-disabled=true])'));
  if (daysInView.length === 0) return;
  const element = daysInView[0];
  const value = element?.getAttribute('data-value');
  const type = element?.getAttribute('data-type');
  if (!value || !type) return;
  return parseAnyDateValue(value, type as DateValueType);
}

/**
 * Ensures the placeholder is not set to a disabled date, which would
 * prevent the user from entering the Calendar via the keyboard.
 */
export function useEnsureNonDisabledPlaceholder({
  ref,
  placeholder,
  defaultPlaceholder,
  minValue,
  maxValue,
  isDateDisabled
}: {
  ref: ReadableBox<HTMLElement | null>;
  placeholder: WritableBox<DateValue>;
  defaultPlaceholder: DateValue;
  minValue: ReadableBox<DateValue | undefined>;
  maxValue: ReadableBox<DateValue | undefined>;
  isDateDisabled: ReadableBox<(date: DateValue) => boolean>;
}) {
  function isDisabled(date: DateValue) {
    if (isDateDisabled.current(date)) return true;
    if (minValue.current && isBefore(date, minValue.current)) return true;
    if (maxValue.current && isBefore(maxValue.current, date)) return true;
    return false;
  }

  watch(
    () => ref.current,
    () => {
      if (!ref.current) return;
      if (
        placeholder.current &&
        isSameDay(placeholder.current, defaultPlaceholder) &&
        isDisabled(defaultPlaceholder)
      ) {
        placeholder.current = getFirstNonDisabledDateInView(ref.current) ?? defaultPlaceholder;
      }
    }
  );
}

export function getDateWithPreviousTime(date: DateValue | undefined, prev: DateValue | undefined) {
  if (!date || !prev) return date;
  if (hasTime(date) && hasTime(prev)) {
    return date.set({
      hour: prev.hour,
      minute: prev.minute,
      millisecond: prev.millisecond,
      second: prev.second
    });
  }
  return date;
}

export const calendarAttrs = createBitsAttrs({
  component: 'calendar',
  parts: [
    'root',
    'grid',
    'cell',
    'next-button',
    'prev-button',
    'day',
    'grid-body',
    'grid-head',
    'grid-row',
    'head-cell',
    'header',
    'heading',
    'month-select',
    'year-select'
  ] as const
});

export function getDefaultYears(opts: {
  minValue: DateValue | undefined;
  maxValue: DateValue | undefined;
  placeholderYear: number;
}) {
  const currentYear = new Date().getFullYear();
  const latestYear = Math.max(opts.placeholderYear, currentYear);
  let minYear: number;
  let maxYear: number;
  if (opts.minValue) {
    minYear = opts.minValue.year;
  } else {
    const initialMinYear = latestYear - 100;
    minYear = opts.placeholderYear < initialMinYear ? opts.placeholderYear - 10 : initialMinYear;
  }
  if (opts.maxValue) {
    maxYear = opts.maxValue.year;
  } else {
    maxYear = latestYear + 10;
  }
  if (minYear > maxYear) {
    minYear = maxYear;
  }
  const totalYears = maxYear - minYear + 1;
  return Array.from({ length: totalYears }, (_, i) => minYear + i);
}

import { type DateValue, getLocalTimeZone, isSameDay, isSameMonth, isToday } from '@internationalized/date';
import { Context, watch } from 'runed';
import { DOMContext, type ReadableBox, type WritableBox, attachRef } from 'svelte-toolbelt';
import { onMount, untrack } from 'svelte';
import { boolToEmptyStrOrUndef, boolToStr, boolToStrTrueOrUndef } from './attrs';
import { getAnnouncer } from './announcer';
import { createFormatter, type Formatter } from './formatter';
import {
  calendarAttrs,
  createAccessibleHeading,
  createMonths,
  getCalendarElementProps,
  getCalendarHeadingValue,
  getDateWithPreviousTime,
  getDefaultYears,
  getIsNextButtonDisabled,
  getIsPrevButtonDisabled,
  getWeekdays,
  handleCalendarKeydown,
  handleCalendarNextPage,
  handleCalendarPrevPage,
  shiftCalendarFocus,
  useEnsureNonDisabledPlaceholder,
  useMonthViewOptionsSync,
  useMonthViewPlaceholderSync
} from './calendar-helpers.svelte';
import { getDateValueType, isBefore, toDate } from './date-utils';
import { useId } from './ids';
import type { DateMatcher, Month, WeekStartsOn } from './types';

type CalendarType = 'single' | 'multiple';

export type CalendarRootStateOpts = {
  id: ReadableBox<string>;
  ref: WritableBox<HTMLElement | null>;
  weekdayFormat: ReadableBox<Intl.DateTimeFormatOptions['weekday']>;
  weekStartsOn: ReadableBox<WeekStartsOn | undefined>;
  pagedNavigation: ReadableBox<boolean>;
  isDateDisabled: ReadableBox<DateMatcher>;
  isDateUnavailable: ReadableBox<DateMatcher>;
  fixedWeeks: ReadableBox<boolean>;
  numberOfMonths: ReadableBox<number>;
  locale: ReadableBox<string>;
  calendarLabel: ReadableBox<string>;
  readonly: ReadableBox<boolean>;
  disabled: ReadableBox<boolean>;
  minValue: ReadableBox<DateValue | undefined>;
  maxValue: ReadableBox<DateValue | undefined>;
  disableDaysOutsideMonth: ReadableBox<boolean>;
  initialFocus: ReadableBox<boolean>;
  maxDays: ReadableBox<number | undefined>;
  placeholder: WritableBox<DateValue>;
  preventDeselect: ReadableBox<boolean>;
  value: WritableBox<DateValue | DateValue[] | undefined>;
  type: ReadableBox<CalendarType>;
  monthFormat: ReadableBox<Intl.DateTimeFormatOptions['month'] | ((month: number) => string)>;
  yearFormat: ReadableBox<Intl.DateTimeFormatOptions['year'] | ((year: number) => string)>;
  defaultPlaceholder: DateValue;
  onDateSelect?: () => void;
};

export const CalendarRootContext = new Context<CalendarRootState>('Calendar.Root | RangeCalendar.Root');

export class CalendarRootState {
  static create(opts: CalendarRootStateOpts) {
    return CalendarRootContext.set(new CalendarRootState(opts));
  }

  opts: CalendarRootStateOpts;
  visibleMonths = $derived.by(() => this.months.map((month) => month.value));
  formatter: Formatter;
  accessibleHeadingId = useId();
  domContext: DOMContext;
  attachment: ReturnType<typeof attachRef<HTMLElement>>;
  months = $state<Month<DateValue>[]>([]);
  announcer: ReturnType<typeof getAnnouncer>;

  constructor(opts: CalendarRootStateOpts) {
    this.opts = opts;
    this.attachment = attachRef(this.opts.ref);
    this.domContext = new DOMContext(opts.ref);
    this.announcer = getAnnouncer(null);
    this.formatter = createFormatter({
      initialLocale: this.opts.locale.current,
      monthFormat: this.opts.monthFormat,
      yearFormat: this.opts.yearFormat
    });

    onMount(() => {
      this.announcer = getAnnouncer(this.domContext.getDocument());
    });

    this.months = createMonths({
      dateObj: this.opts.placeholder.current,
      weekStartsOn: this.opts.weekStartsOn.current,
      locale: this.opts.locale.current,
      fixedWeeks: this.opts.fixedWeeks.current,
      numberOfMonths: this.opts.numberOfMonths.current
    });

    this.#setupInitialFocusEffect();
    this.#setupAccessibleHeadingEffect();
    this.#setupFormatterEffect();

    useMonthViewPlaceholderSync({
      placeholder: this.opts.placeholder,
      getVisibleMonths: () => this.visibleMonths,
      weekStartsOn: this.opts.weekStartsOn,
      locale: this.opts.locale,
      fixedWeeks: this.opts.fixedWeeks,
      numberOfMonths: this.opts.numberOfMonths,
      setMonths: (months) => (this.months = months)
    });

    useMonthViewOptionsSync({
      fixedWeeks: this.opts.fixedWeeks,
      locale: this.opts.locale,
      numberOfMonths: this.opts.numberOfMonths,
      placeholder: this.opts.placeholder,
      setMonths: this.setMonths,
      weekStartsOn: this.opts.weekStartsOn
    });

    watch(
      () => this.fullCalendarLabel,
      (label) => {
        const node = this.domContext.getElementById(this.accessibleHeadingId);
        if (!node) return;
        node.textContent = label;
      }
    );

    watch(
      () => this.opts.value.current,
      () => {
        const value = this.opts.value.current;
        if (Array.isArray(value) && value.length) {
          const lastValue = value[value.length - 1];
          if (lastValue && this.opts.placeholder.current !== lastValue) {
            this.opts.placeholder.current = lastValue;
          }
        } else if (!Array.isArray(value) && value && this.opts.placeholder.current !== value) {
          this.opts.placeholder.current = value;
        }
      }
    );

    useEnsureNonDisabledPlaceholder({
      placeholder: opts.placeholder,
      defaultPlaceholder: opts.defaultPlaceholder,
      isDateDisabled: opts.isDateDisabled,
      maxValue: opts.maxValue,
      minValue: opts.minValue,
      ref: opts.ref
    });
  }

  setMonths = (months: Month<DateValue>[]) => {
    this.months = months;
  };

  weekdays = $derived.by(() => {
    return getWeekdays({
      months: this.months,
      formatter: this.formatter,
      weekdayFormat: this.opts.weekdayFormat.current
    });
  });

  initialPlaceholderYear = $derived.by(() => untrack(() => this.opts.placeholder.current.year));
  defaultYears = $derived.by(() => {
    return getDefaultYears({
      minValue: this.opts.minValue.current,
      maxValue: this.opts.maxValue.current,
      placeholderYear: this.initialPlaceholderYear
    });
  });

  #setupInitialFocusEffect() {
    $effect(() => {
      const initialFocus = untrack(() => this.opts.initialFocus.current);
      if (initialFocus) {
        const firstFocusedDay = this.opts.ref.current?.querySelector<HTMLElement>('[data-focused]');
        firstFocusedDay?.focus();
      }
    });
  }

  #setupAccessibleHeadingEffect() {
    $effect(() => {
      if (!this.opts.ref.current) return;
      const removeHeading = createAccessibleHeading({
        calendarNode: this.opts.ref.current,
        label: this.fullCalendarLabel,
        accessibleHeadingId: this.accessibleHeadingId
      });
      return removeHeading;
    });
  }

  #setupFormatterEffect() {
    $effect.pre(() => {
      if (this.formatter.getLocale() === this.opts.locale.current) return;
      this.formatter.setLocale(this.opts.locale.current);
    });
  }

  nextPage = () => {
    handleCalendarNextPage({
      fixedWeeks: this.opts.fixedWeeks.current,
      locale: this.opts.locale.current,
      numberOfMonths: this.opts.numberOfMonths.current,
      pagedNavigation: this.opts.pagedNavigation.current,
      setMonths: this.setMonths,
      setPlaceholder: (date) => (this.opts.placeholder.current = date),
      weekStartsOn: this.opts.weekStartsOn.current,
      months: this.months
    });
  };

  prevPage = () => {
    handleCalendarPrevPage({
      fixedWeeks: this.opts.fixedWeeks.current,
      locale: this.opts.locale.current,
      numberOfMonths: this.opts.numberOfMonths.current,
      pagedNavigation: this.opts.pagedNavigation.current,
      setMonths: this.setMonths,
      setPlaceholder: (date) => (this.opts.placeholder.current = date),
      weekStartsOn: this.opts.weekStartsOn.current,
      months: this.months
    });
  };

  nextYear = () => {
    this.opts.placeholder.current = this.opts.placeholder.current.add({ years: 1 });
  };

  prevYear = () => {
    this.opts.placeholder.current = this.opts.placeholder.current.subtract({ years: 1 });
  };

  setYear = (year: number) => {
    this.opts.placeholder.current = this.opts.placeholder.current.set({ year });
  };

  setMonth = (month: number) => {
    this.opts.placeholder.current = this.opts.placeholder.current.set({ month });
  };

  isNextButtonDisabled = $derived.by(() => {
    return getIsNextButtonDisabled({
      maxValue: this.opts.maxValue.current,
      months: this.months,
      disabled: this.opts.disabled.current
    });
  });

  isPrevButtonDisabled = $derived.by(() => {
    return getIsPrevButtonDisabled({
      minValue: this.opts.minValue.current,
      months: this.months,
      disabled: this.opts.disabled.current
    });
  });

  isInvalid = $derived.by(() => {
    const value = this.opts.value.current;
    const isDateDisabled = this.opts.isDateDisabled.current;
    const isDateUnavailable = this.opts.isDateUnavailable.current;
    if (Array.isArray(value)) {
      if (!value.length) return false;
      for (const date of value) {
        if (isDateDisabled(date)) return true;
        if (isDateUnavailable(date)) return true;
      }
    } else {
      if (!value) return false;
      if (isDateDisabled(value)) return true;
      if (isDateUnavailable(value)) return true;
    }
    return false;
  });

  headingValue = $derived.by(() => {
    void this.opts.monthFormat.current;
    void this.opts.yearFormat.current;
    return getCalendarHeadingValue({
      months: this.months,
      formatter: this.formatter,
      locale: this.opts.locale.current
    });
  });

  fullCalendarLabel = $derived.by(() => `${this.opts.calendarLabel.current} ${this.headingValue}`);

  isOutsideVisibleMonths = (date: DateValue) => {
    return !this.visibleMonths.some((month) => isSameMonth(date, month));
  };

  isDateDisabled = (date: DateValue) => {
    if (this.opts.isDateDisabled.current(date) || this.opts.disabled.current) return true;
    const minValue = this.opts.minValue.current;
    const maxValue = this.opts.maxValue.current;
    if (minValue && isBefore(date, minValue)) return true;
    if (maxValue && isBefore(maxValue, date)) return true;
    return false;
  };

  isDateSelected = (date: DateValue) => {
    const value = this.opts.value.current;
    if (Array.isArray(value)) {
      return value.some((d) => isSameDay(d, date));
    }
    if (!value) return false;
    return isSameDay(value, date);
  };

  shiftFocus = (node: HTMLElement, add: number) => {
    return shiftCalendarFocus({
      node,
      add,
      placeholder: this.opts.placeholder,
      calendarNode: this.opts.ref.current,
      isPrevButtonDisabled: this.isPrevButtonDisabled,
      isNextButtonDisabled: this.isNextButtonDisabled,
      months: this.months,
      numberOfMonths: this.opts.numberOfMonths.current
    });
  };

  #isMultipleSelectionValid(selectedDates: DateValue[]) {
    if (this.opts.type.current !== 'multiple') return true;
    if (!this.opts.maxDays.current) return true;
    const selectedCount = selectedDates.length;
    if (this.opts.maxDays.current && selectedCount > this.opts.maxDays.current) return false;
    return true;
  }

  handleCellClick = (_: Event, date: DateValue) => {
    if (this.opts.readonly.current || this.opts.isDateDisabled.current?.(date) || this.opts.isDateUnavailable.current?.(date)) {
      return;
    }
    const prev = this.opts.value.current;
    const multiple = this.opts.type.current === 'multiple';
    if (multiple) {
      if (Array.isArray(prev) || prev === undefined) {
        this.opts.value.current = this.handleMultipleUpdate(prev, date);
      }
    } else if (!Array.isArray(prev)) {
      const next = this.handleSingleUpdate(prev, date);
      if (!next) {
        this.announcer.announce('Selected date is now empty.', 'polite', 5000);
      } else {
        this.announcer.announce(`Selected Date: ${this.formatter.selectedDate(next, false)}`, 'polite');
      }
      this.opts.value.current = getDateWithPreviousTime(next, prev);
      if (next !== undefined) {
        this.opts.onDateSelect?.();
      }
    }
  };

  handleMultipleUpdate = (prev: DateValue[] | undefined, date: DateValue): DateValue[] | undefined => {
    if (!prev) {
      const newSelection = [date];
      return this.#isMultipleSelectionValid(newSelection) ? newSelection : [date];
    }
    const index = prev.findIndex((d) => isSameDay(d, date));
    const preventDeselect = this.opts.preventDeselect.current;
    if (index === -1) {
      const newSelection = [...prev, date];
      if (this.#isMultipleSelectionValid(newSelection)) {
        return newSelection;
      }
      return [date];
    }
    if (preventDeselect) {
      return prev;
    }
    const next = prev.filter((d) => !isSameDay(d, date));
    if (!next.length) {
      this.opts.placeholder.current = date;
      return undefined;
    }
    return next;
  };

  handleSingleUpdate = (prev: DateValue | undefined, date: DateValue): DateValue | undefined => {
    if (!prev) return date;
    const preventDeselect = this.opts.preventDeselect.current;
    if (!preventDeselect && isSameDay(prev, date)) {
      this.opts.placeholder.current = date;
      return undefined;
    }
    return date;
  };

  onkeydown = (event: KeyboardEvent) => {
    handleCalendarKeydown({
      event,
      handleCellClick: this.handleCellClick,
      shiftFocus: this.shiftFocus,
      placeholderValue: this.opts.placeholder.current
    });
  };

  snippetProps = $derived.by(() => ({
    months: this.months,
    weekdays: this.weekdays
  }));

  getBitsAttr = (part: string) => {
    return calendarAttrs.getAttr(part);
  };

  props = $derived.by(
    () =>
      ({
        ...getCalendarElementProps({
          fullCalendarLabel: this.fullCalendarLabel,
          id: this.opts.id.current,
          isInvalid: this.isInvalid,
          disabled: this.opts.disabled.current,
          readonly: this.opts.readonly.current
        }),
        [this.getBitsAttr('root')]: '',
        onkeydown: this.onkeydown,
        ...this.attachment
      }) as Record<string, unknown>
  );
}

export type CalendarHeadingStateOpts = {
  id: ReadableBox<string>;
  ref: WritableBox<HTMLElement | null>;
};

export class CalendarHeadingState {
